package ama.api;
import ama.transcript.*;import ama.storage.*;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Fail after an actual production generation-input INSERT and prove the acceptance transaction rolls back. */
public final class LocalGenerationRollbackCheck {
 static final class Fault extends AbstractDataSource {
  final DataSource delegate;boolean armed,inserted;Fault(DataSource delegate){this.delegate=delegate;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> type,InvocationHandler h){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement statement)return proxy(statement,PreparedStatement.class,(s,sm,sa)->{Object value=invoke(statement,sm,sa);if(armed&&!inserted&&sm.getName().equals("executeUpdate")&&sql.startsWith("INSERT INTO generation_input(")){inserted=true;throw new SQLException("LOCAL_QUALIFICATION_AFTER_GENERATION_INPUT_INSERT");}return value;});return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static Map<String,Object> snapshot(JdbcTemplate j,String meeting){var map=new LinkedHashMap<>(LocalActionOwnerCheck.snapshot(j,meeting));for(String table:List.of("generation_input","generation_candidate"))map.put(table,j.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE meeting_id=?",Long.class,meeting));map.put("tasks",j.queryForObject("SELECT COUNT(*) FROM durable_task WHERE subject_kind='MEETING' AND subject_id=?",Long.class,meeting));return map;}
 public static void main(String[] args)throws Exception{
  LocalActionOwnerCheck.check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==2,"Explicit daily check required");Path file=Path.of(args[0]).toRealPath();LocalActionOwnerCheck.check(file.getParent().endsWith(Path.of(".tools/local-app"))&&Files.size(file)<65536,"Daily config required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");LocalActionOwnerCheck.check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");String meeting=args[1];UUID.fromString(meeting);var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var fault=new Fault(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var source=new LocalAcquisitionBudgetCheck.Source(fault);var j=new JdbcTemplate(source);j.setQueryTimeout(5);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));var configured=ConfiguredProcessing.read(env);
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);long revision=j.queryForObject("SELECT revision FROM meeting WHERE id=? AND ever_published=0 AND final_confirmation_id IS NULL",Long.class,meeting);var before=snapshot(j,meeting);runtime.tx().required(()->{try{runtime.minutes().generation().enqueue(actor,meeting,UUID.randomUUID().toString(),revision,UUID.randomUUID().toString());throw new AssertionError("Ambient generation command must reject");}catch(IllegalStateException expected){LocalActionOwnerCheck.check(expected.getMessage().contains("ambient transaction"),"Actual ambient guard required");}return null;});LocalActionOwnerCheck.check(before.equals(snapshot(j,meeting)),"Ambient generation has no effects");
   RuntimeException rejected=null;fault.armed=true;try{runtime.minutes().generation().enqueue(actor,meeting,UUID.randomUUID().toString(),revision,UUID.randomUUID().toString());}catch(RuntimeException failed){rejected=failed;}finally{fault.armed=false;}LocalActionOwnerCheck.check(fault.inserted&&rejected!=null,"Actual generation-input INSERT must run before injected failure");Throwable cause=rejected;boolean intended=false;for(;cause!=null;cause=cause.getCause())if(cause instanceof SQLException&&cause.getMessage().equals("LOCAL_QUALIFICATION_AFTER_GENERATION_INPUT_INSERT"))intended=true;LocalActionOwnerCheck.check(intended,"Only the intended actual-after-write rejection qualifies");LocalActionOwnerCheck.check(before.equals(snapshot(j,meeting)),"Input/graph/root/projection/task/receipt/audit/outbox must rollback");System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",true,"meetingId",meeting,"genuineFactories",true,"actualGenerationInputInsertExecuted",true,"forcedFailureRolledBackAcceptance",true,"ambientCommandRejected",true,"zeroSnapshotChanges",true,"newAcceptedTask",false)));
  }
 }
}
